      "min": 240,
      "max": 480,
      "step": 10,
      "unit": "px",
      "default": 340
    },
    {
      "type": "checkbox",
      "id": "motion",
      "label": "Enable button hover motion",
      "default": true
    },
    {
      "type": "range",
      "id": "speed",
      "label": "Hover speed",
      "min": 50,
      "max": 200,
      "step": 10,
      "unit": "%",
      "default": 100
    }
  ],
  "blocks": [
    {
      "type": "pour",
      "name": "Pour and product",
      "limit": 3,
      "settings": [
        {
          "type": "text",
          "id": "label",
          "label": "Pour label",
          "default": "Everyday"
        },
        {
          "type": "product",
          "id": "product",
          "label": "Product"
        },
        {
          "type": "text",
          "id": "name",
          "label": "Short product name"
        },
        {
          "type": "text",
          "id": "detail",
          "label": "Product detail"
        },
        {
          "type": "image_picker",
          "id": "image",
          "label": "Desktop scene override"
        },
        {
          "type": "image_picker",
          "id": "mobile_image",
          "label": "Mobile scene override"
        },
        {
          "type": "range",
