        {
          "type": "font_picker",
          "id": "heading_font",
          "label": "Font family",
          "default": "poppins_n4"
        },
        {
          "type": "range",
          "id": "heading_weight",
          "label": "Thickness",
          "min": 100,
          "max": 900,
          "step": 100,
          "default": 900
        },
        {
          "type": "range",
          "id": "heading_size",
          "label": "Desktop size",
          "min": 10,
          "max": 100,
          "step": 1,
          "unit": "px",
          "default": 62
        },
        {
          "type": "range",
          "id": "heading_mobile",
          "label": "Mobile size",
          "min": 10,
          "max": 80,
          "step": 1,
          "unit": "px",
          "default": 42
        },
        {
          "type": "range",
          "id": "heading_tracking",
          "label": "Letter spacing",
          "min": -6,
          "max": 20,
          "step": 1,
          "unit": "%",
          "default": -2
        },
        {
          "type": "range",
          "id": "heading_leading",
          "label": "Line height",
          "min": 90,
          "max": 200,
          "step": 5,
          "unit": "%",
          "default": 105
        },
        {
          "type": "header",
          "content": "Product title"
        },
        {
          "type": "font_picker",
          "id": "title_font",
          "label": "Font family",
          "default": "poppins_n4"
        },
        {
          "type": "range",
          "id": "title_weight",
          "label": "Thickness",
          "min": 100,
          "max": 900,
          "step": 100,
          "default": 600
        },
        {
          "type": "range",
          "id": "title_size",
          "label": "Desktop size",
